    /*
     * Add to the Sites
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Tenant
     */
    public Tenant addToSites( UUID parentId, Site addTo ) {
	    LOGGER.info("handling AssignSitesToTenantEvent - " );
	    
	    Tenant parentEntity = repository.findById(parentId).get();
	    Site child = registry.project( Site.class, addTo.getSiteId());
	    
	    parentEntity.getSites().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Sites
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Tenant
     */
	public Tenant removeFromSites( UUID parentId, Site removeFrom ) {
	    LOGGER.info("handling RemoveSitesFromTenantEvent " );
	
	    Tenant parentEntity = repository.findById(parentId).get();
	    Site child = registry.project( Site.class, removeFrom.getSiteId());
	    
	    parentEntity.getSites().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

