    /**
     * Method to retrieve the Tenant via an FindTenantQuery
     * @return 	query	FindTenantQuery
     */
    @SuppressWarnings("unused")
    public Tenant find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Tenant - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Tenants
     *
     * @param	query	FindAllTenantQuery 
     * @return 	List<Tenant> 
     */
    @SuppressWarnings("unused")
    public List<Tenant> findAll( FindAllTenantQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Tenant - {0}", exc.getMessage() );
    	}
    	return null;
    }


